import {DEITIES,BY_ID,FAVOUR,ENEMIES,MAPS,enemyKey} from './data.js';
import {Battle} from './engine.js';
import {SAVE_KEY,PROGRESS_KEY,emptyJourney,migrateJourney,recordVictory,introductions,challengeProgress} from './campaign.js';
import {createRenderer,paintEnemyPortrait} from './renderer.js';
const $=id=>document.getElementById(id),canvas=$('board'),images={};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let stored=read(PROGRESS_KEY,null),journey=stored?.version===2?stored:migrateJourney(read('temple-guardians-progress-v1',{}));
if(!journey.temples||!Array.isArray(journey.seen)||!Array.isArray(journey.stories)||!Array.isArray(journey.festival))journey=emptyJourney();
let saved=read(SAVE_KEY,null),battle;
try{battle=new Battle(saved?.version===2&&MAPS[saved.mapIndex]?saved.mapIndex:0,saved?.version===2?saved:null);}catch{battle=new Battle();}
let paused=battle.status==='fighting',speed=1,selectedPlot=null,selectedDeity='agni',sound=false,audio=null,endHandled=false,wonAge=0,ready=false,last=0,uiClock=0,saveClock=0,confirmAction=null,pendingWave=null,introCards=[],introIndex=0;
const draw=createRenderer(canvas,images),activeDialogs=()=>!!document.querySelector('dialog[open]');
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify({...battle.snapshot(),version:2}));localStorage.setItem(PROGRESS_KEY,JSON.stringify(journey));}catch{$('message').textContent='Browser storage is unavailable; progress cannot be saved after closing.';}}
function tone(kind){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();let notes=kind==='upgrade'?[523,784,1046]:kind==='wave'?[196,294]:kind==='won'?[523,659,784,1046]:kind==='leak'?[150]:[440,660];notes.forEach((f,i)=>{let o=audio.createOscillator(),g=audio.createGain();o.type=kind==='wave'?'triangle':'sine';o.frequency.value=f;let t=audio.currentTime+i*.11;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.075,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+.7);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.75);});}catch{sound=false;$('sound').textContent='Sound unavailable';}}
function spriteStyle(d,level=1){return `background-image:url('assets/${level===3?'exalted':level===2?'honoured':'shrines'}.webp');background-position:${(d.atlas%4)/3*100}% ${d.atlas<4?0:100}%;`;}
function sprite(d,level=1,klass='selection-art'){return `<div class="${klass} sprite-shrine tier-${level}" style="${spriteStyle(d,level)}" aria-hidden="true"></div>`;}
function refreshPlots(){$('plotSelect').innerHTML='<option value="">Tap a numbered plot</option>'+battle.map.plots.map((_,i)=>{let s=battle.shrines.find(s=>s.plot===i);return `<option value="${i}">Plot ${i+1}${s?' — '+BY_ID[s.deity].name:''}</option>`;}).join('');$('plotSelect').value=selectedPlot===null?'':String(selectedPlot);}
function initRoster(){$('deities').innerHTML=DEITIES.map(d=>`<button class="deity" data-deity="${d.id}" style="--accent:${d.colour}" aria-label="${d.name}: ${d.role}, ${d.cost} offerings">${sprite(d,1,'thumb')}<span class="deity-name">${d.name}</span><span class="role">${d.role}</span><span class="price">${d.cost} <span>offerings</span></span><i class="accent-line"></i></button>`).join('');for(let button of document.querySelectorAll('[data-deity]'))button.onclick=()=>{if(!ready)return;selectedDeity=button.dataset.deity;let s=battle.shrines.find(s=>s.plot===selectedPlot);if(selectedPlot!==null&&!s){if(!battle.build(selectedPlot,selectedDeity))battle.message='More offerings are needed for this shrine.';refreshPlots();}else if(s){selectedPlot=null;refreshPlots();battle.message='Choose an empty plot for your next shrine.';}else battle.message=`Choose a plot to establish ${BY_ID[selectedDeity].name}.`;updateSelection();updateUI();save();};}
function updateSelection(){let s=battle.shrines.find(s=>s.plot===selectedPlot),d=BY_ID[s?.deity||selectedDeity];
 if(selectedPlot===null)$('selection').innerHTML=`${sprite(d)}<h2>${d.name}</h2><div class="selection-domain" style="color:${d.colour}">${d.domain} · ${d.role}</div><p>${d.description}</p><p class="selection-hint">Choose a numbered plot to establish a shrine. All seven deities deal damage.</p>`;
 else if(!s)$('selection').innerHTML=`<h2>Plot ${selectedPlot+1}</h2><p>Choose a shrine below, or establish ${d.name} here.</p>${sprite(d)}<div class="selection-actions"><button id="build" class="primary">Establish ${d.name} · ${d.cost}</button></div>`;
 else $('selection').innerHTML=`${sprite(d,s.level)}<h2>${d.name}</h2><div class="selection-domain" style="color:${d.colour}">${FAVOUR[s.level-1]} · Plot ${s.plot+1}</div><div class="favour-level">${[1,2,3].map(i=>`<i class="${i<=s.level?'on':''}"></i>`).join('')}</div><p>${d.description}</p>${s.level<3?`<div class="upgrade-preview"><span>NEXT: ${FAVOUR[s.level].toUpperCase()}</span><p>${d.changes[s.level-1]}</p></div>`:'<p class="upgrade-preview">Exalted favour. This shrine has reached its full strength.</p>'}<div class="selection-actions">${s.level<3?`<button id="upgrade" class="primary">Raise favour · ${d.upgrade[s.level-1]}</button>`:'<button disabled>Exalted shrine</button>'}<button id="intervene">Call intervention</button><button id="sell" class="sell">Rebuild elsewhere · return ${Math.floor(s.spent*.85)}</button></div><p class="intervention-help">${d.intervention}</p>`;
 if($('build'))$('build').onclick=()=>{if(battle.build(selectedPlot,selectedDeity)){refreshPlots();updateSelection();updateUI();save();}};
 if($('upgrade'))$('upgrade').onclick=()=>{battle.upgrade(selectedPlot);updateSelection();updateUI();save();};
 if($('sell'))$('sell').onclick=()=>{battle.sell(selectedPlot);refreshPlots();updateSelection();updateUI();save();};
 if($('intervene'))$('intervene').onclick=()=>{battle.intervention(selectedPlot);updateSelection();updateUI();save();};
 for(let button of document.querySelectorAll('[data-deity]')){let active=button.dataset.deity===d.id;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active));}
}
function preview(){let next=battle.wave<8?battle.waves[battle.wave]:null,current=battle.waves[Math.max(0,battle.wave-1)],entries=next||current;$('previewTitle').textContent=battle.status==='won'?'Temple restored':next?`Next wave · ${battle.wave+1}`:`Final wave · 8`;
 if(battle.status==='won'){$('previewEnemies').innerHTML='<span class="enemy-chip">The army has been turned back.</span>';$('boonText').textContent='';return;}
 const groups={};for(let e of entries){let key=e.type+'|'+(e.protection||'');groups[key]??={...e,count:0};groups[key].count++;}
 $('previewEnemies').innerHTML=Object.values(groups).map(e=>`<span class="enemy-chip">${e.count} × ${e.type==='boss'?battle.map.bossName:ENEMIES[e.type].name}${e.protection?`<small>${BY_ID[e.protection].name}’s protection</small>`:e.type==='shade'?'<small>Hidden · Saraswati reveals</small>':''}</span>`).join('');
 $('boonText').textContent=entries.some(e=>e.type==='boss')?battle.map.boon:entries.some(e=>e.type==='winged')?'Flying foes evade Durga’s blocking guardian. Vayu’s wind deals extra damage.':'';
}
function updateUI(){
 $('offerings').textContent=battle.offerings;$('shield').textContent=`${battle.shield} / ${battle.map.shield}`;$('wave').textContent=`${battle.wave} / 8`;$('mapName').textContent=battle.map.name;$('chapterLabel').textContent=battle.map.subtitle.toUpperCase();$('meterValue').textContent=Math.floor(battle.meter)+'%';$('meterFill').style.width=battle.meter+'%';$('meterFill').parentElement.classList.toggle('ready',battle.meter>=100);
 $('pause').textContent=paused?'Resume':'Pause';$('pause').setAttribute('aria-pressed',String(paused));$('pause').disabled=battle.status!=='fighting';
 $('waveButton').disabled=!ready||battle.status!=='planning';$('waveButton').textContent=battle.status==='planning'?`Begin wave ${battle.wave+1} →`:battle.status==='fighting'?`Wave ${battle.wave} in progress`:battle.status==='won'?'Temple restored':'Battle ended';
 $('earlyButton').hidden=battle.status!=='fighting'||battle.wave>=8;$('earlyButton').disabled=!battle.canCallEarly();$('earlyButton').textContent=battle.canCallEarly()?`Call wave ${battle.wave+1} early · +${battle.earlyReward()}`:'Early call available after foes arrive';
 $('message').textContent=paused&&battle.status==='fighting'?'Paused. Build, upgrade or plan your next intervention.':battle.message;
 $('progressText').textContent=`${Object.keys(journey.temples).length} / 5 temples restored · saved on this browser`;
 $('challengeName').textContent=battle.map.challenge;$('challengeProgress').textContent=challengeProgress(battle);
 $('activeWaves').textContent=battle.activeWaves.length>1?`Waves ${battle.activeWaves.join(' + ')} overlap`:battle.status==='fighting'?`${battle.enemies.length} foes on the path`:battle.status==='won'?'The river journey continues':'One battle · eight waves';
 let s=battle.shrines.find(s=>s.plot===selectedPlot);if($('upgrade'))$('upgrade').disabled=battle.offerings<BY_ID[s.deity].upgrade[s.level-1]||['won','lost'].includes(battle.status);if($('intervene'))$('intervene').disabled=battle.meter<100||battle.status!=='fighting';if($('build'))$('build').disabled=!ready||battle.offerings<BY_ID[selectedDeity].cost||['won','lost'].includes(battle.status);preview();
 for(let e of battle.events.splice(0))tone(e.type);
 if(['won','lost'].includes(battle.status)&&!endHandled){endHandled=true;wonAge=0;showResult();}
}
function lampsHTML(lamps,labels=true){return `<div class="achievement-lamps">${['Victory','Shield intact','Challenge'].map((name,i)=>`<span class="achievement ${lamps[i]?'lit':''}" aria-label="${name}: ${lamps[i]?'earned':'not yet earned'}"><span aria-hidden="true">🪔</span>${labels?`<small>${name}</small>`:''}</span>`).join('')}</div>`;}
function showResult(){const won=battle.status==='won',reward=won?recordVictory(journey,battle):null;
 if(reward?.festivalUnlocked&&!journey.festival.includes(battle.map.id))journey.festival.push(battle.map.id);save();
 $('result').hidden=false;$('result').innerHTML=`<span class="panel-eyebrow">${won?'THE LIGHT RETURNS':'THE DEFENCE HAS FALLEN'}</span><h2>${won?battle.map.name+' restored':'The shield has fallen'}</h2><p>${won?battle.map.outro:'The murtis still stand. Try another balance of damage, control and revelation.'}</p>${won?lampsHTML(reward.lamps):''}${reward?.festivalUnlocked?'<p class="festival-reward">All three lamps lit. Festival decorations unlocked.</p>':''}<div class="result-buttons">${won&&battle.mapIndex<4?'<button class="primary" id="nextTemple">Continue upriver →</button>':''}<button id="retry">${won?'Replay for the lamps':'Try again'}</button><button id="lookAround">${won?'See the restored temple':'See the battlefield'}</button></div>${won?`<p class="story-next">${battle.map.next}</p>`:''}`;
 $('retry').onclick=()=>newBattle(battle.mapIndex);if($('nextTemple'))$('nextTemple').onclick=()=>newBattle(battle.mapIndex+1);$('lookAround').onclick=()=>{$('result').hidden=true;$('victoryDetails').hidden=false;};
}
function choosePlot(i){selectedPlot=i;let s=battle.shrines.find(s=>s.plot===i);if(s)selectedDeity=s.deity;refreshPlots();updateSelection();updateUI();}
canvas.addEventListener('pointerdown',e=>{if(!ready)return;let rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*1200,y=(e.clientY-rect.top)/rect.height*650,nearest=-1,best=Infinity;battle.map.plots.forEach(([px,py],i)=>{let distance=Math.hypot(px-x,py-y);if(battle.shrines.some(s=>s.plot===i)&&Math.abs(px-x)<50&&y>py-150&&y<py+18)distance=Math.min(distance,18);if(distance<best){best=distance;nearest=i;}});if(best<62)choosePlot(nearest);});
$('plotSelect').onchange=e=>{if(e.target.value===''){selectedPlot=null;updateSelection();}else choosePlot(Number(e.target.value));};
function openDialog(id){$(id).showModal();}function closeDialog(id){$(id).close();}
function openStory(){const m=battle.map;$('storyArt').src=`assets/${m.art}.webp`;$('storyChapter').textContent=m.subtitle;$('storyTitle').textContent=m.name;$('storyIntro').textContent=m.intro;$('keeperWords').textContent=m.keeper;$('storyChallenge').textContent=m.challenge;openDialog('storyDialog');}
$('storyContinue').onclick=()=>{if(!journey.stories.includes(battle.map.id))journey.stories.push(battle.map.id);closeDialog('storyDialog');save();};$('chapterStory').onclick=openStory;
function requestWave(early=false){if(!ready||pendingWave||activeDialogs())return;if(early?!battle.canCallEarly():battle.status!=='planning')return;pendingWave={early};introCards=introductions(battle.waves[battle.wave],battle.mapIndex,journey.seen);introIndex=0;if(introCards.length){renderIntroduction();openDialog('enemyDialog');}else finishWaveRequest();}
function renderIntroduction(){const card=introCards[introIndex];$('enemyName').textContent=card.name;$('enemyQuote').textContent='“'+card.quote+'”';$('enemyHint').textContent=card.hint;$('enemyProtection').textContent=card.protectionText;$('enemyProtection').hidden=!card.protectionText;$('enemyCounter').textContent=`NEW FOE · ${introIndex+1} / ${introCards.length}`;$('enemyContinue').textContent=introIndex+1<introCards.length?'Meet the next foe →':pendingWave?.early?'Call the wave early':'Begin the wave →';paintEnemyPortrait($('enemyPortrait'),images.enemies,card.family);}
function finishWaveRequest(){let request=pendingWave;pendingWave=null;if(!request)return;for(let card of introCards)if(!journey.seen.includes(card.key))journey.seen.push(card.key);if($('enemyDialog').open)closeDialog('enemyDialog');battle.startWave(request.early);paused=false;updateUI();save();}
$('enemyContinue').onclick=()=>{if(++introIndex<introCards.length)renderIntroduction();else finishWaveRequest();};$('enemyCancel').onclick=()=>{pendingWave=null;closeDialog('enemyDialog');};$('enemyDialog').addEventListener('cancel',()=>{pendingWave=null;});
$('waveButton').onclick=()=>requestWave(false);$('earlyButton').onclick=()=>requestWave(true);$('pause').onclick=()=>{paused=!paused;updateUI();save();};$('speed').onclick=()=>{speed={1:2,2:5,5:1}[speed];$('speed').textContent=speed+'×';$('speed').setAttribute('aria-label',`Battle speed ${speed} times. Click to change.`);};
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));if(sound)tone('upgrade');};$('guide').onclick=()=>openDialog('guideDialog');
for(let b of document.querySelectorAll('[data-close]'))b.onclick=()=>closeDialog(b.dataset.close);
function openCampaign(){const count=Object.keys(journey.temples).length;$('journeySummary').textContent=count===5?'The river flows through every restored temple. Return to earn the remaining lamps.':`${count} of 5 temples restored. Follow the river towards its source.`;
 $('mapChoices').innerHTML=MAPS.map((m,i)=>{let progress=journey.temples[m.id],lamps=progress?.lamps||[false,false,false],festival=lamps.every(Boolean);return `<article class="journey-stop ${progress?'restored':''}"><span class="journey-number">${i+1}</span><button class="map-choice" data-map="${i}"><img src="assets/${m.art}.webp" alt="${m.name}"><div><small>${m.subtitle}</small><strong>${m.name}</strong><span>${progress?'Restored · best shield '+progress.shield+'/20':m.note}</span>${lampsHTML(lamps,false)}</div></button>${festival?`<button class="festival-toggle" data-festival="${m.id}" aria-pressed="${journey.festival.includes(m.id)}">Festival decoration: ${journey.festival.includes(m.id)?'on':'off'}</button>`:''}</article>`;}).join('');
 for(let b of document.querySelectorAll('[data-map]'))b.onclick=()=>{closeDialog('campaignDialog');const i=Number(b.dataset.map);if(battle.wave>0&&!['won','lost'].includes(battle.status))askConfirm('Leave this battle?','This battle will restart. Restored temples and earned lamps remain saved.','Change temple',()=>newBattle(i));else newBattle(i);};
 for(let b of document.querySelectorAll('[data-festival]'))b.onclick=()=>{const id=b.dataset.festival;if(journey.festival.includes(id))journey.festival=journey.festival.filter(x=>x!==id);else journey.festival.push(id);b.textContent='Festival decoration: '+(journey.festival.includes(id)?'on':'off');b.setAttribute('aria-pressed',String(journey.festival.includes(id)));save();};openDialog('campaignDialog');
}
$('campaign').onclick=openCampaign;
function openJournal(){const cards=[],keys=new Set();for(let i=0;i<MAPS.length;i++)for(let specs of new Battle(i).waves)for(let spec of specs){const key=enemyKey(spec,i);if(keys.has(key)||!journey.seen.includes(key))continue;keys.add(key);cards.push(...introductions([spec],i,[]));}
 $('journalList').innerHTML=cards.length?cards.map((card,i)=>`<details class="journal-entry"><summary>${card.name}${card.protection?' · '+BY_ID[card.protection].name+'’s protection':''}</summary><div><canvas id="journal-${i}" width="110" height="140" aria-label="${card.name}"></canvas><p>${card.hint}${card.protectionText?' '+card.protectionText:''}</p></div></details>`).join(''):'<p>New enemies will be recorded here after their first introduction.</p>';cards.forEach((card,i)=>paintEnemyPortrait($('journal-'+i),images.enemies,card.family));openDialog('journalDialog');}
$('journal').onclick=openJournal;
function newBattle(i){battle=new Battle(i);paused=false;selectedPlot=null;endHandled=false;wonAge=0;pendingWave=null;$('result').hidden=true;$('victoryDetails').hidden=true;refreshPlots();updateSelection();updateUI();save();openStory();}
function askConfirm(title,text,label,action){$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmYes').textContent=label;confirmAction=action;openDialog('confirmDialog');}
$('restart').onclick=()=>askConfirm('Restart this battle?','Current shrines and offerings will reset. Restored temples and achievement lamps remain saved.','Restart',()=>newBattle(battle.mapIndex));$('confirmCancel').onclick=()=>closeDialog('confirmDialog');$('confirmYes').onclick=()=>{closeDialog('confirmDialog');confirmAction?.();};$('victoryDetails').onclick=()=>{$('result').hidden=false;$('victoryDetails').hidden=true;};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&battle.status==='fighting'){paused=true;save();updateUI();}});window.addEventListener('pagehide',save);document.addEventListener('keydown',e=>{if(e.code==='Space'&&!activeDialogs()&&!['BUTTON','SELECT','INPUT'].includes(document.activeElement.tagName)){e.preventDefault();if(battle.status==='fighting')$('pause').click();}});
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;const stopped=paused||activeDialogs();if(!stopped)for(let i=0;i<speed;i++)battle.tick(dt);if(!stopped||battle.status!=='fighting')battle.animate(dt);if(battle.status==='won')wonAge+=dt;draw(battle,{now:stopped?battle.time*1000:now,paused:stopped,selectedPlot,selectedDeity,journey,wonAge});uiClock+=dt;saveClock+=dt;if(uiClock>.2){updateUI();uiClock=0;}if(saveClock>3){save();saveClock=0;}requestAnimationFrame(frame);}
initRoster();refreshPlots();updateSelection();updateUI();
async function loadArt(){const names=['courtyard','lotus','town','mountain','spring','shrines','honoured','exalted','spells','restoration','enemies','guardian'];await Promise.all(names.map(name=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{images[name]=img;resolve();};img.onerror=()=>reject(new Error(name));img.src=`assets/${name}.webp`;})));ready=true;$('loading').hidden=true;updateUI();last=performance.now();requestAnimationFrame(frame);if(!saved?.version&&!journey.stories.includes(battle.map.id))openStory();}
loadArt().catch(()=>{$('loading').innerHTML='Some artwork could not load. <button id="retryLoad">Try again</button>';$('retryLoad').onclick=()=>location.reload();});
